<?php
require_once __DIR__ . '/includes/bootstrap.php'; adminRequireLogin(); ensureMisTables(); $conn=adminDb();
if(adminVerifyPost()&&isset($_POST['reconcile_cod'])){$id=(int)($_POST['collection_id']??0);$decision=$_POST['decision']??'';$note=trim($_POST['note']??'');if(!$id||!in_array($decision,['reconciled','disputed'],true))adminRedirect('delivery-mis.php','Choose a valid COD decision.');$s=mysqli_prepare($conn,'UPDATE cod_collections SET status=?,reconciled_at=IF(?="reconciled",NOW(),NULL),admin_note=? WHERE collection_id=? AND status IN ("recorded","pending")');mysqli_stmt_bind_param($s,'sssi',$decision,$decision,$note,$id);mysqli_stmt_execute($s);adminRedirect('delivery-mis.php',$decision==='reconciled'?'COD collection reconciled.':'COD collection marked disputed for follow-up.');}
if(adminVerifyPost()&&isset($_POST['resolve_failure'])){$assignment=(int)($_POST['assignment_id']??0);$orderId=(int)($_POST['orderid']??0);$decision=$_POST['decision']??'';if(!$assignment||!$orderId||!in_array($decision,['returned','cancelled'],true))adminRedirect('delivery-mis.php','Choose a valid failed-delivery decision.');if(!mysqli_begin_transaction($conn))adminRedirect('delivery-mis.php','Could not begin the delivery resolution.');$s=mysqli_prepare($conn,'UPDATE order_delivery_assignments SET is_current=0 WHERE assignment_id=? AND status="failed"');mysqli_stmt_bind_param($s,'i',$assignment);$ok=mysqli_stmt_execute($s);$transition=orderTransition($orderId,$decision,'admin',$_SESSION['admin_email'],'Failed delivery resolved by admin');$ok=$ok&&$transition[0];$ok?mysqli_commit($conn):mysqli_rollback($conn);adminRedirect('delivery-mis.php',$ok?'Failed delivery resolved.':($transition[1]??'Could not resolve this delivery.'));}
$cod=adminRows("SELECT c.*,o.name customer_name,r.name rider_name FROM cod_collections c JOIN orders o ON o.orderid=c.orderid JOIN delivery_riders r ON r.rider_id=c.rider_id WHERE c.status IN ('pending','recorded','disputed') ORDER BY c.recorded_at DESC,c.collection_id DESC");
$failed=adminRows("SELECT a.assignment_id,a.orderid,a.failure_reason,a.assigned_at,o.name customer_name,r.name rider_name FROM order_delivery_assignments a JOIN orders o ON o.orderid=a.orderid JOIN delivery_riders r ON r.rider_id=a.rider_id WHERE a.is_current=1 AND a.status='failed' ORDER BY a.assigned_at DESC");
$adminTitle='Delivery control';$adminPage='operations';include __DIR__.'/includes/header.php';
?><section class="admin-card"><div class="admin-toolbar"><div><p class="admin-kicker">Delivery MIS</p><h2>COD reconciliation</h2><p class="admin-muted">Rider-recorded cash is not final until an administrator reconciles it.</p></div><a class="admin-btn secondary" href="operations.php"><i class="bi bi-truck"></i>Delivery operations</a></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Rider</th><th>Expected / recorded</th><th>Rider record</th><th>Decision</th></tr></thead><tbody><?php foreach($cod as $row){?><tr><td>#<?php echo (int)$row['orderid'];?><br><span class="admin-muted"><?php echo adminEscape($row['customer_name']);?></span></td><td><?php echo adminEscape($row['rider_name']);?></td><td><strong>Rs <?php echo number_format((float)$row['expected_amount']);?></strong><br><span class="admin-muted">Rs <?php echo number_format((float)($row['collected_amount']??0));?> recorded</span></td><td><span class="admin-badge <?php echo $row['status']==='recorded'?'live':'muted';?>"><?php echo adminEscape(ucfirst($row['status']));?></span></td><td><?php if(in_array($row['status'],['pending','recorded'],true)){?><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken());?>"><input type="hidden" name="collection_id" value="<?php echo (int)$row['collection_id'];?>"><input name="note" maxlength="500" placeholder="Optional reconciliation note"><button class="admin-btn" name="reconcile_cod" value="1" onclick="this.form.decision.value='reconciled'">Reconcile</button><button class="admin-btn danger" name="reconcile_cod" value="1" onclick="this.form.decision.value='disputed'">Dispute</button><input type="hidden" name="decision"></form><?php }else{echo adminEscape($row['admin_note']?:'Resolved');}?></td></tr><?php }?></tbody></table><?php if(!$cod){?><p class="admin-muted">No COD collections need review.</p><?php }?></div></section>
<section class="admin-card"><div class="admin-toolbar"><div><h2>Failed-delivery resolution</h2><p class="admin-muted">Choose a final operational outcome. Reassignment is handled from Delivery operations after an order returns to the dispatch queue.</p></div><span class="admin-badge muted"><?php echo count($failed);?> open</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Rider</th><th>Issue</th><th>Assigned</th><th>Resolution</th></tr></thead><tbody><?php foreach($failed as $row){?><tr><td>#<?php echo (int)$row['orderid'];?><br><span class="admin-muted"><?php echo adminEscape($row['customer_name']);?></span></td><td><?php echo adminEscape($row['rider_name']);?></td><td><?php echo adminEscape($row['failure_reason']?:'No reason provided');?></td><td><?php echo adminEscape($row['assigned_at']);?></td><td><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken());?>"><input type="hidden" name="assignment_id" value="<?php echo (int)$row['assignment_id'];?>"><input type="hidden" name="orderid" value="<?php echo (int)$row['orderid'];?>"><button class="admin-btn secondary" name="resolve_failure" value="1" onclick="this.form.decision.value='returned'">Return order</button><button class="admin-btn danger" name="resolve_failure" value="1" onclick="this.form.decision.value='cancelled'">Cancel order</button><input type="hidden" name="decision"></form></td></tr><?php }?></tbody></table><?php if(!$failed){?><p class="admin-muted">No failed deliveries awaiting resolution.</p><?php }?></div></section><?php include __DIR__.'/includes/footer.php'; ?>
